return items.map(item => {
  const v = item.json;

  return {
    json: {
      videoId: v.videoId,
      prompt: `
VIDEO ID: ${v.videoId}
TITLE: ${v.title}

CHANNEL: ${v.context.match(/CHANNEL:\s*(.*)/)?.[1] || "Unknown"}

DESCRIPTION:
${v.context}

TAGS:
${(v.bullet_summary || []).join(", ")}

INTENT: ${v.intent}
QUALITY SCORE: ${v.quality_score}
      `.trim()
    }
  };
});

function isoDurationToSeconds(iso) {
  const match = iso.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  return (
    (parseInt(match?.[1] || 0) * 3600) +
    (parseInt(match?.[2] || 0) * 60) +
    (parseInt(match?.[3] || 0))
  );
}

function extractTimestamps(text) {
  if (!text) return [];

  const regex = /(\d{1,2}:\d{2}(?::\d{2})?)\s*[-–]?\s*(.+)/g;
  const results = [];
  let match;

  while ((match = regex.exec(text)) !== null) {
    results.push({
      time: match[1],
      label: match[2].trim(),
    });
  }

  return results;
}

function cleanText(text = "") {
  return text
    .replace(/https?:\/\/\S+/g, "") // remove links
    .replace(/\n{2,}/g, "\n") // normalize spacing
    .trim();
}

function extractTopics(text, tags = []) {
  const words = text
    .toLowerCase()
    .split(/[^a-zA-Z0-9]+/)
    .filter(w => w.length > 4);

  const freq = {};
  for (const w of words) {
    freq[w] = (freq[w] || 0) + 1;
  }

  const topWords = Object.entries(freq)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 8)
    .map(([w]) => w);

  return [...new Set([...tags.slice(0, 10), ...topWords])].slice(0, 12);
}

return items.flatMap(item => {
  const video = item.json.items?.[0];
  if (!video) return [];

  const snippet = video.snippet || {};
  const description = snippet.description || "";
  const title = snippet.title || "";

  const cleanedDescription = cleanText(description);
  const timestamps = extractTimestamps(description);

  const output = {
    videoId: video.id,
    title,
    channel: snippet.channelTitle,
    publishedAt: snippet.publishedAt,

    language: snippet.defaultLanguage || snippet.defaultAudioLanguage || "unknown",

    durationSeconds: video.contentDetails?.duration
      ? isoDurationToSeconds(video.contentDetails.duration)
      : null,

    tags: snippet.tags || [],

    timestamps,

    summary_input: cleanedDescription,

    topics: extractTopics(cleanedDescription, snippet.tags || []),

    sourceType: "youtube_metadata"
  };

  return [{ json: output }];
});

function buildContext(video) {
  const title = video.title || "";
  const channel = video.channel || "";
  const desc = video.summary_input || "";

  return `TITLE: ${title}
CHANNEL: ${channel}

CONTENT:
${desc}`;
}

function extractChapters(timestamps = []) {
  return timestamps.map(t => ({
    time: t.time,
    topic: t.label
  }));
}

function detectIntent(text = "") {
  const t = text.toLowerCase();

  if (t.includes("trading") || t.includes("market") || t.includes("stock")) return "finance";
  if (t.includes("ai") || t.includes("claude") || t.includes("automation")) return "ai_tools";
  if (t.includes("news")) return "news";

  return "general";
}

function scoreQuality(video) {
  let score = 50;

  if (video.durationSeconds > 600) score += 10;
  if (video.timestamps?.length > 3) score += 10;
  if (video.tags?.length > 5) score += 10;
  if (video.summary_input?.length > 500) score += 10;

  return Math.min(score, 100);
}

return items.map(item => {
  const v = item.json;

  return {
    json: {
      videoId: v.videoId,
      title: v.title,

      context: buildContext(v),

      bullet_summary: [
        `Channel: ${v.channel}`,
        `Duration: ${v.durationSeconds}s`,
        `Language: ${v.language}`,
        `Topics: ${(v.topics || []).slice(0, 8).join(", ")}`
      ],

      chapters: extractChapters(v.timestamps || []),

      intent: detectIntent(v.summary_input),

      quality_score: scoreQuality(v)
    }
  };
});
